#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

struct avl_node {
    int value;
    int height;
    struct avl_node *left;
    struct avl_node *right;
};

struct avl_node *root = NULL;

static int avl_height(struct avl_node *n) {
    return n ? n->height : 0;
}

static int avl_max(int a, int b) {
    return (a > b) ? a : b;
}

static struct avl_node* new_node(int value) {
    struct avl_node* node = (struct avl_node*)malloc(sizeof(struct avl_node));
    if (!node) exit(1);
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    node->height = 1;
    return node;
}

static struct avl_node *right_rotate(struct avl_node *y) {
    struct avl_node *x = y->left;
    struct avl_node *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = avl_max(avl_height(y->left), avl_height(y->right)) + 1;
    x->height = avl_max(avl_height(x->left), avl_height(x->right)) + 1;

    return x;
}

static struct avl_node *left_rotate(struct avl_node *x) {
    struct avl_node *y = x->right;
    struct avl_node *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = avl_max(avl_height(x->left), avl_height(x->right)) + 1;
    y->height = avl_max(avl_height(y->left), avl_height(y->right)) + 1;

    return y;
}

static int get_balance(struct avl_node *n) {
    return n ? avl_height(n->left) - avl_height(n->right) : 0;
}

static struct avl_node* avl_insert_node(struct avl_node* node, int value) {
    if (node == NULL)
        return new_node(value);

    if (value < node->value)
        node->left = avl_insert_node(node->left, value);
    else if (value > node->value)
        node->right = avl_insert_node(node->right, value);
    else 
        return node;

    node->height = 1 + avl_max(avl_height(node->left), avl_height(node->right));

    int balance = get_balance(node);

    if (balance > 1 && value < node->left->value)
        return right_rotate(node);

    if (balance < -1 && value > node->right->value)
        return left_rotate(node);

    if (balance > 1 && value > node->left->value) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }

    if (balance < -1 && value < node->right->value) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }

    return node;
}

void avl_insert(int value) {
    root = avl_insert_node(root, value);
}

static struct avl_node *min_value_node(struct avl_node *node) {
    struct avl_node *current = node;
    while (current->left != NULL)
        current = current->left;
    return current;
}

static struct avl_node* avl_delete_node(struct avl_node* node, int value) {
    if (node == NULL)
        return node;

    if (value < node->value)
        node->left = avl_delete_node(node->left, value);
    else if (value > node->value)
        node->right = avl_delete_node(node->right, value);
    else {
        if ((node->left == NULL) || (node->right == NULL)) {
            struct avl_node *temp = node->left ? node->left : node->right;
            if (temp == NULL) {
                temp = node;
                node = NULL;
            } else {
                *node = *temp;
            }
            free(temp);
        } else {
            struct avl_node *temp = min_value_node(node->right);
            node->value = temp->value;
            node->right = avl_delete_node(node->right, temp->value);
        }
    }

    if (node == NULL)
        return node;

    node->height = 1 + avl_max(avl_height(node->left), avl_height(node->right));
    int balance = get_balance(node);

    if (balance > 1 && get_balance(node->left) >= 0)
        return right_rotate(node);

    if (balance > 1 && get_balance(node->left) < 0) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }

    if (balance < -1 && get_balance(node->right) <= 0)
        return left_rotate(node);

    if (balance < -1 && get_balance(node->right) > 0) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }

    return node;
}

void avl_delete(int value) {
    root = avl_delete_node(root, value);
}

static bool verify_bst(struct avl_node *node, int min, int max) {
    if (node == NULL) return true;
    if (node->value <= min || node->value >= max) return false;
    return verify_bst(node->left, min, node->value) && verify_bst(node->right, node->value, max);
}

static bool verify_balance(struct avl_node *node) {
    if (node == NULL) return true;
    int lh = avl_height(node->left);
    int rh = avl_height(node->right);
    if (abs(lh - rh) > 1) return false;
    if (node->height != 1 + avl_max(lh, rh)) return false;
    return verify_balance(node->left) && verify_balance(node->right);
}

int main(void) {
    for (int i = 1; i <= 1000; i++) {
        avl_insert(i);
    }
    for (int i = 1; i <= 500; i++) {
        avl_delete(i * 2); 
    }
    if (!verify_bst(root, -1000000, 1000000)) {
        printf("BST property failed!\n");
        return 1;
    }
    if (!verify_balance(root)) {
        printf("Balance property failed!\n");
        return 1;
    }
    printf("FLAG: AVL-Tree Success!\n");
    return 0;
}
